138	  private _appendProcessTeardownDiagnostics(error: TestInfoError) {
139	    if (!this._lastRunningTests.length)
140	      return;
141	    const count = this._totalRunningTests === 1 ? '1 test' : `${this._totalRunningTests} tests`;
142	    let lastMessage = '';
143	    if (this._lastRunningTests.length < this._totalRunningTests)
144	      lastMessage = `, last ${this._lastRunningTests.length} tests were`;
145	    const message = [
146	      '',
147	      '',
148	      colors.red(`Failed worker ran ${count}${lastMessage}:`),
149	      ...this._lastRunningTests.map(test => formatTestTitle(test, this._project.project.name)),
150	    ].join('\n');
151	    if (error.message) {
152	      if (error.stack) {
153	        let index = error.stack.indexOf(error.message);
154	        if (index !== -1) {
155	          index += error.message.length;
156	          error.stack = error.stack.substring(0, index) + message + error.stack.substring(index);
157	        }
158	      }
159	      error.message += message;
160	    } else if (error.value) {
161	      error.value += message;
162	    }
163	  }
