165	  unhandledError(error: Error | any) {
166	    // No current test - fatal error.
167	    if (!this._currentTest) {
168	      if (!this._fatalErrors.length)
169	        this._fatalErrors.push(testInfoError(error));
170	      void this._stop();
171	      return;
172	    }
173	
174	    // We do not differentiate between errors in the control flow
175	    // and unhandled errors - both lead to the test failing. This is good for regular tests,
176	    // so that you can, e.g. expect() from inside an event handler. The test fails,
177	    // and we restart the worker.
178	    if (!this._currentTest._hasUnhandledError) {
179	      this._currentTest._hasUnhandledError = true;
180	      this._currentTest._failWithError(error);
181	    }
182	
183	    // For tests marked with test.fail(), this might be a problem when unhandled error
184	    // is not coming from the user test code (legit failure), but from fixtures or test runner.
185	    //
186	    // Ideally, we would mark this test as "failed unexpectedly" and show that in the report.
187	    // However, we do not have such a special test status, so the test will be considered ok (failed as expected).
188	    //
189	    // To avoid messing up future tests, we forcefully stop the worker, unless it is
190	    // an expect() error which we know does not mess things up.
191	    const isExpectError = (error instanceof Error) && !!(error as any).matcherResult;
192	    const shouldContinueInThisWorker = this._currentTest.expectedStatus === 'failed' && isExpectError;
193	    if (!shouldContinueInThisWorker) {
194	      this._stoppedDueToUnhandledErrorInTestFail = true;
195	      void this._stop();
196	    }
197	  }
